/*
 * Atribuir tópico, como o assign do Discourse (backend em extend/assign.php):
 *
 * - "Atribuir…" nos controles de moderação de quem tem a permissão;
 * - a pílula "Atribuído a [avatar] Fulano" no cabeçalho do tópico e na lista;
 * - "Atribuídos a mim" na barra lateral de quem atribui: a lista em /assigned.
 */
import app from 'flarum/forum/app';
import { extend } from 'flarum/common/extend';
import Button from 'flarum/common/components/Button';
import LinkButton from 'flarum/common/components/LinkButton';
import Avatar from 'flarum/common/components/Avatar';
import Link from 'flarum/common/components/Link';
import username from 'flarum/common/helpers/username';
import DiscussionControls from 'flarum/forum/utils/DiscussionControls';
import DiscussionHero from 'flarum/forum/components/DiscussionHero';
import DiscussionListItem from 'flarum/forum/components/DiscussionListItem';
import DiscussionListState from 'flarum/forum/states/DiscussionListState';
import IndexSidebar from 'flarum/forum/components/IndexSidebar';
import { t } from '../../utils/settings';
const assignee = discussion => discussion.canelaAssignee?.() || null;
function pill(user) {
  return m(Link, {
    className: "CanelaAssignee",
    href: app.route.user(user),
    title: t('assign.assigned_to', {
      username: username(user)
    })
  }, m("span", {
    className: "CanelaAssignee-label"
  }, t('assign.label')), m(Avatar, {
    user: user
  }), m("span", {
    className: "CanelaAssignee-name"
  }, username(user)));
}
export default function installAssign() {
  extend(DiscussionControls, 'moderationControls', function (items, discussion) {
    if (!discussion.attribute('canCanelaAssign')) return;
    items.add('canelaAssign', m(Button, {
      icon: "fas fa-user-check",
      onclick: () => app.modal.show(() => import(/* webpackChunkName: 'forum/features/assign/AssignModal', webpackMode: 'lazy-once' */ './AssignModal'), {
        discussion
      })
    }, assignee(discussion) ? t('assign.change') : t('assign.action')));
  });
  extend(DiscussionHero.prototype, 'items', function (items) {
    const user = assignee(this.attrs.discussion);
    if (user) items.add('canelaAssignee', pill(user), -20);
  });
  extend(DiscussionListItem.prototype, 'infoItems', function (items) {
    const user = assignee(this.attrs.discussion);
    if (user) items.add('canelaAssignee', pill(user), 5);
  });
  extend(IndexSidebar.prototype, 'navItems', function (items) {
    if (!app.forum.attribute('canelaCanAssign')) return;
    items.add('canelaAssigned', m(LinkButton, {
      href: app.route('canela.assigned'),
      icon: "fas fa-user-check"
    }, t('assign.nav')), 65);
  });
  extend(DiscussionListState.prototype, 'requestParams', function (params) {
    if (app.current.get('routeName') !== 'canela.assigned') return;
    params.filter = {
      ...(params.filter || {}),
      canelaAssigned: 'me'
    };
  });

  // Pelo nome do módulo: o NotificationGrid vem no pedaço da página de
  // configurações, carregado sob demanda.
  extend('flarum/forum/components/NotificationGrid', 'notificationTypes', function (items) {
    items.add('canelaAssigned', {
      name: 'canelaAssigned',
      icon: 'fas fa-user-check',
      label: t('assign.setting')
    });
  });
}
flarum.reg.add('ramon-canela', 'forum/features/assign', installAssign);flarum.reg.addChunkModule('forum/features/assign/AssignModal', './src/forum/features/assign/AssignModal.tsx', 'ramon-canela', 'forum/features/assign/AssignModal');